LICENSES = {'Visual Studio': {'total_seats': 20, 'used_seats': 20}, 'Adobe Creative Cloud': {'total_seats': 15, 'used_seats': 9}, 'Slack Pro': {'total_seats': 100, 'used_seats': 87}, 'Zoom Business': {'total_seats': 80, 'used_seats': 61}, 'Jira': {'total_seats': 50, 'used_seats': 48}, 'Figma': {'total_seats': 12, 'used_seats': 12}, 'Tableau': {'total_seats': 10, 'used_seats': 4}, 'Salesforce': {'total_seats': 25, 'used_seats': 22}}

VPN_STATUS = {'mumbai-office': 'operational', 'pune-office': 'degraded - investigating', 'remote-gateway': 'operational', 'bangalore-office': 'operational', 'delhi-office': 'outage - ETA 2 hours'}


# ---- the actual "tools" the agent can call ----

def check_shared_drive_access(employee_id: str) -> dict:
    """Looks up whether an employee has shared drive access."""
    emp = EMPLOYEES.get(employee_id)
    if not emp:
        return {"error": f"No employee found with ID {employee_id}"}
    return {"employee": emp["name"], "has_access": emp["shared_drive_access"]}

def check_license_availability(software_name: str) -> dict:
    """Checks how many license seats are available for a piece of software."""
    lic = LICENSES.get(software_name)
    if not lic:
        return {"error": f"No license record for {software_name}. Available: {list(LICENSES.keys())}"}
    available = lic["total_seats"] - lic["used_seats"]
    return {"software": software_name, "seats_available": available, "total_seats": lic["total_seats"]}

def check_vpn_status(location: str) -> dict:
    """Checks current VPN/network status for a location."""
    status = VPN_STATUS.get(location)
    if not status:
        return {"error": f"No status for {location}. Known locations: {list(VPN_STATUS.keys())}"}
    return {"location": location, "status": status}

def check_badge_access(employee_id: str) -> dict:
    """Checks whether an employee badge is currently active."""
    emp = EMPLOYEES.get(employee_id)
    if not emp:
        return {"error": f"No employee found with ID {employee_id}"}
    return {"employee": emp["name"], "badge_active": emp["badge_active"], "location": emp["location"]}
